PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS products(id INTEGER PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,price REAL NOT NULL CHECK(price>=0),image TEXT,collection TEXT NOT NULL DEFAULT 'hoodies',runway INTEGER NOT NULL DEFAULT 0,sort INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS variants(id INTEGER PRIMARY KEY,product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,size TEXT NOT NULL,sku TEXT UNIQUE NOT NULL,stock INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE COLLATE NOCASE,name TEXT NOT NULL,phone TEXT,password_hash TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY,email TEXT NOT NULL,total REAL NOT NULL,status TEXT NOT NULL DEFAULT 'new',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  user_id INTEGER REFERENCES users(id),reference TEXT,ship_name TEXT,ship_phone TEXT,ship_address TEXT,ship_city TEXT,notes TEXT,
  payment_method TEXT NOT NULL DEFAULT 'cod',payment_status TEXT NOT NULL DEFAULT 'unpaid',currency TEXT,shipping REAL NOT NULL DEFAULT 0,provider_ref TEXT,updated_at TEXT);
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,variant_id INTEGER NOT NULL REFERENCES variants(id),quantity INTEGER NOT NULL CHECK(quantity BETWEEN 1 AND 20),unit_price REAL NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id) ON DELETE CASCADE,provider TEXT NOT NULL,provider_txn_id TEXT NOT NULL,amount_cents INTEGER,currency TEXT,status TEXT NOT NULL,raw TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(provider,provider_txn_id));
CREATE TABLE IF NOT EXISTS subscribers(email TEXT PRIMARY KEY,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS identities(provider TEXT NOT NULL,subject TEXT NOT NULL,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(provider,subject));
CREATE TABLE IF NOT EXISTS collections(slug TEXT PRIMARY KEY,title TEXT NOT NULL,sort INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS looks(id INTEGER PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,tagline TEXT,image TEXT,sort INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS look_items(look_id INTEGER NOT NULL REFERENCES looks(id) ON DELETE CASCADE,product_id INTEGER NOT NULL REFERENCES products(id) ON DELETE CASCADE,sort INTEGER NOT NULL DEFAULT 0,pin_x REAL,pin_y REAL,is_new INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(look_id,product_id));
CREATE TABLE IF NOT EXISTS addresses(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,label TEXT,name TEXT NOT NULL,phone TEXT NOT NULL,address TEXT NOT NULL,city TEXT NOT NULL,is_default INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS addresses_user ON addresses(user_id);
